/// <summary>
/// Tender Matrix Helper class
/// </summary>
class KCS_KBVTenderIdUtility
{
}

Method.Source:
/// <summary>
/// Checks if a string can be inserted into a bigger matrix
/// </summary>
/// <param name = "_insertString">string</param>
/// <param name = "_CompMatrix">matrix</param>
/// <returns>true or false</returns>
public static boolean CanBeInsertedInBiggerMatrix(str _insertString, container _CompMatrix)
{
    container   insertMatrix;
    int         i;
    ;
    insertMatrix    = KCS_KBVTenderIdUtility::KCS_CreateTenderMatrix(_insertString);

    if (conlen(insertMatrix) > conlen(_CompMatrix))
    {
        return false;
    }
    else
    {
        for(i = 1; i <= conlen(insertMatrix); i++)
        {
            if (conpeek(insertMatrix,i) > conpeek(_CompMatrix,i))
            {
                return false;
            }
        }
    }
    return true;
}

/// <summary>
/// Creates a new Tender matrix
/// </summary>
/// <param name = "_LVPos">LV position</param>
/// <param name = "_CompMatrix">matrix</param>
/// <returns>new matrix container </returns>
public static container CreateNewTenderMatrix(str _LVPos, container _CompMatrix)
{
    container   lVMatrix, newMatrix, maxMatrix, minMatrix;
    int         i,j;
    ;
    lVMatrix    =  KCS_KBVTenderIdUtility::KCS_CreateTenderMatrix(_LVPos);

    if (conlen(lVMatrix) > conlen(_CompMatrix))
    {
        maxMatrix   = lVMatrix;
        minMatrix   = _CompMatrix;
    }
    else
    {
        maxMatrix   = _CompMatrix;
        minMatrix   = lVMatrix;
    }

    j = 1;
    for (i = 1; i <= conlen(maxMatrix); i++)
    {
        if (i <= conlen(maxMatrix) - conlen(minMatrix))
        {
            newMatrix   += conpeek(maxMatrix,i);
        }
        else
        {
            newMatrix += max(conpeek(maxMatrix,i),conpeek(minMatrix,j));
            j++;
        }
    }
    return newMatrix;
}

/// <summary>
/// Fills matrix
/// </summary>
/// <param name = "_fillStr">string</param>
/// <param name = "_Matrix">matrix</param>
/// <returns>string</returns>
public static str fillMatrix(str _fillStr, container _Matrix)
{
    int         i,j,k,part;
    container   fillMatrix, fillCont, newCont;
    str         hilf;
    ;
    fillMatrix  = KCS_KBVTenderIdUtility::KCS_CreateTenderMatrix(_fillStr);
    fillCont    = KCS_str2con(_fillStr,'.');

    #localmacro.sethilf
    hilf   = '0' + hilf;
    #endmacro

    j = 1;
    for (i = 1; i <= conlen(_Matrix); i++)
    {
        if (i <= conlen(_Matrix) - conlen(fillMatrix))
        {
            k = 1;
            part    = conpeek(_Matrix,i);
            hilf    = '';
            while (k <= part)
            {
                #sethilf
                k++;
            }
            newCont += hilf;
        }
        else
        {
            hilf    = conpeek(fillCont,j);
            while (strlen(hilf) < conpeek(_Matrix,i))
            {
                #sethilf
            }
            j++;
            newCont  += hilf;
        }
    }

    return Con2Str(newCont,'.');
}

/// <summary>
/// Can a string be inserted into a matrix
/// </summary>
/// <param name = "_insertString">string</param>
/// <param name = "_CompMatrix">matrix</param>
/// <returns>true or false</returns>
public static boolean KCS_CanBeInsertedInMatrix(str _insertString, container _CompMatrix)
{
    container   insertMatrix;
    int         i;
    ;
    insertMatrix    = KCS_KBVTenderIdUtility::KCS_CreateTenderMatrix(_insertString);

    if (conlen(insertMatrix) != conlen(_CompMatrix))
    {
        return false;
    }
    else
    {
        for(i = 1; i <= conlen(insertMatrix); i++)
        {
            if (conpeek(insertMatrix,i) != conpeek(_CompMatrix,i))
            {
                return false;
            }
        }
    }
    return true;
}

/// <summary>
/// Creates tender matrix
/// </summary>
/// <param name = "_LVPos">LV position</param>
/// <returns>container</returns>
public static container KCS_CreateTenderMatrix(str _LVPos)
{
    int         i;
    container   LVContainer, MatrixContainer;
    str         hilf;
    ;
    LVContainer = KCS_str2con(_LVPos,'.');
    for(i = 1; i <= conlen(LVContainer); i++)
    {
        hilf    = conpeek(LVContainer,i);

        MatrixContainer += strlen(hilf);
    }
    return MatrixContainer;

}

/// <summary>
/// rearranges matrix
/// </summary>
/// <param name = "_quotationId">Quotation id</param>
public static void rearrangeMatrix(QuotationId _quotationId)
{
    SalesQuotationLine salesQuotationLine;
    KCS_KBVSalesTenderLink salesTenderLink;
    ;
    ttsbegin;
    while select forUpdate salesQuotationLine where salesQuotationLine.QuotationId == _quotationId
    {
        salesQuotationLine.KCS_QLLVPosition = KCS_Con2str(str2con(salesQuotationLine.KCS_QLLVPosition,'.'),'.');
        salesQuotationLine.doUpdate();
    }
    ttscommit;


    ttsbegin;
    salesTenderLink = KCS_KBVSalesTenderLink::find(_quotationId,true);
    salesTenderLink.delete();
    salesQuotationLine.clear();

    salesTenderLink = KCS_KBVSalesTenderLink::find(_quotationId,true);
    while select salesQuotationLine order by KCS_QLLVPosition desc
        where salesQuotationLine.QuotationId == _quotationId
    {
        if (!KCS_KBVTenderIdUtility::KCS_CanBeInsertedInMatrix(salesQuotationLine.KCS_QLLVPosition,salesTenderLink.TenderMatrix))
        {
            salesTenderLink.TenderMatrix = KCS_KBVTenderIdUtility::CreateNewTenderMatrix(salesQuotationLine.KCS_QLLVPosition,salesTenderLink.TenderMatrix);
            if (salesTenderLink.RecId)
            {
                salesTenderLink.update();
            }
            else
            {
                salesTenderLink.QuotationId = _quotationId;
                salesTenderLink.insert();
            }
        }
    }

    salesTenderLink = KCS_KBVSalesTenderLink::find(_quotationId);
    while select forUpdate salesQuotationLine where salesQuotationLine.QuotationId == _quotationId
    {
        salesQuotationLine.KCS_QLLVPosition = KCS_KBVTenderIdUtility::fillMatrix(salesQuotationLine.KCS_QLLVPosition,salesTenderLink.TenderMatrix);
        salesQuotationLine.LineNum  = salesQuotationLine.buildLineNumFromLVPos();
        salesQuotationLine.doUpdate();
    }
    ttscommit;
}
